// The signals arrive from "Fetch Zara signals", an HTTP Request node on the
// stored Supabase credential; this node used to fetch them with the
// service-role key written into its source (moved 2026-10-03).
const res = $input.first().json.body;
const signals = Array.isArray(res) ? res : [];
if (signals.length === 0) {
  return [{ json: { signals: [], hasSignals: false } }];
}
return [{ json: { signals, hasSignals: true } }];

// Every row this run produces is inserted in one call by "Write pipeline
// tasks", an HTTP Request node on the stored Supabase credential. These
// nodes used to POST their own rows with the service-role key written into
// their source (moved 2026-10-03).
const zaraData = $('Zara: Fetch Signals').first().json;
const enrichment = $input.first().json || {};
const signals = zaraData.signals || [];
const newsletterThemes = Array.isArray(enrichment.newsletter_themes) ? enrichment.newsletter_themes : [];
const inspirationNotes = Array.isArray(enrichment.inspiration_notes) ? enrichment.inspiration_notes : [];

const zaraTopics = signals.map(s => s.title || s.description || '').filter(Boolean);
const zaraKeywords = signals.flatMap(s => {
  const meta = typeof s.metadata === 'string' ? JSON.parse(s.metadata || '{}') : (s.metadata || {});
  return meta.keywords || [];
});

const allTopics = zaraTopics.concat(newsletterThemes);

const brief = {
  title: 'Content Brief - ' + new Date().toISOString().split('T')[0],
  trending_topics: zaraTopics,
  newsletter_themes: newsletterThemes,
  inspiration_notes: inspirationNotes,
  keywords: [...new Set(zaraKeywords)],
  competitor_gaps: signals.filter(s => {
    const meta = typeof s.metadata === 'string' ? JSON.parse(s.metadata || '{}') : (s.metadata || {});
    return meta.type === 'competitor_gap';
  }).map(s => s.title || s.description),
  source_signal_ids: signals.map(s => s.id),
  enrichment_cost_usd: enrichment.cost_usd || 0,
  enrichment_api_calls: enrichment.api_calls || 0,
  generated_at: new Date().toISOString()
};

const task = {
  agent: 'cleo',
  title: brief.title,
  description: 'Content brief from ' + signals.length + ' Zara signals + ' + newsletterThemes.length + ' newsletter themes',
  status: 'done',
  type: 'content_brief',
  metadata: JSON.stringify(brief)
};
return [{ json: { brief, newsletter_worthy: allTopics.length >= 2, rows: [task] } }];

// Every row this run produces is inserted in one call by "Write pipeline
// tasks", an HTTP Request node on the stored Supabase credential. These
// nodes used to POST their own rows with the service-role key written into
// their source (moved 2026-10-03).
const brief = $input.first().json.brief;
const posts = brief.trending_topics.slice(0, 3).map((topic, i) => {
  const hashtags = brief.keywords.slice(0, 3).map(k => '#' + k.replace(/\s+/g, '')).join(' ');
  return {
    agent: 'maya',
    title: 'Social Post: ' + topic.substring(0, 60),
    description: 'Draft social post about: ' + topic,
    status: 'pending',
    type: 'social_post',
    metadata: JSON.stringify({
      copy_suggestion: 'New insight from our research: ' + topic + '. ' + hashtags,
      platform: i === 0 ? 'twitter' : i === 1 ? 'linkedin' : 'instagram',
      source_brief: brief.title,
      keywords: brief.keywords.slice(0, 5),
      scheduled_for: new Date(Date.now() + (i + 1) * 3600000).toISOString()
    })
  };
});
const rows = ($input.first().json.rows || []).concat(posts);
return [{ json: { posts_created: posts.length, brief_title: brief.title, newsletter_worthy: $input.first().json.newsletter_worthy, rows } }];

// Every row this run produces is inserted in one call by "Write pipeline
// tasks", an HTTP Request node on the stored Supabase credential. These
// nodes used to POST their own rows with the service-role key written into
// their source (moved 2026-10-03).
const data = $input.first().json;
const rows = (data.rows || []).slice();
if (data.newsletter_worthy) {
  rows.push({
    agent: 'felix',
    title: 'Newsletter Candidate: ' + data.brief_title,
    description: 'Content pipeline produced ' + data.posts_created + ' social posts. Review for newsletter inclusion.',
    status: 'pending',
    type: 'newsletter_candidate',
    metadata: JSON.stringify({
      source: 'content_pipeline',
      posts_created: data.posts_created,
      brief_title: data.brief_title,
      tagged: 'newsletter_candidate'
    })
  });
  return [{ json: { felix_queued: true, posts_created: data.posts_created, brief_title: data.brief_title, rows } }];
}
return [{ json: { felix_queued: false, posts_created: data.posts_created, brief_title: data.brief_title, rows } }];
